const $=id=>document.getElementById(id), money=n=>n===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),num=n=>Number(n)>0&&Number(n)<1e-8?'<0.00000001':new Intl.NumberFormat('en-US',{maximumFractionDigits:8}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function toast(s){clearTimeout(toastTimer);$('toast').textContent=s;$('toast').classList.remove('hidden');toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),7000)}

let providerRequestTail=Promise.resolve();

async function api(path,data){if(path.startsWith('market-')||path.startsWith('intelligence-'))return rawApi(path,data);if(['sync','refresh-prices','history','wallet-details','discover-tokens','market-listings','market-detail','market-chart','market-fundamentals','market-news','intelligence-overview','intelligence-narrative','intelligence-rsi','intelligence-venues','intelligence-flow','intelligence-derivatives','intelligence-exposures','market-watch-toggle','market-watchlist'].includes(path)){const pending=providerRequestTail.then(()=>rawApi(path,data));providerRequestTail=pending.catch(()=>{});return pending}return rawApi(path,data)}

async function rawApi(path,data){const controller=new AbortController(),readOnly=!data||/^(market-(listings|detail|chart|quote|fundamentals|news|watchlist)|intelligence-(overview|narrative|rsi|venues|flow|derivatives|exposures))$/.test(path),timer=setTimeout(()=>controller.abort(),readOnly?30000:90000);try{const r=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',method:data?'POST':'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,signal:controller.signal});let j;try{j=await r.json()}catch(cause){if(cause.name==='AbortError')throw cause;const error=Error(r.ok?'The server returned an unreadable response. Please try again.':'The service is temporarily unavailable. Please try again.');error.status=r.status;throw error}if(!r.ok){const error=Error(typeof j?.error==='string'?j.error:'Request failed. Please try again.');error.status=r.status;throw error}return j}catch(error){if(error.name==='AbortError')throw Error('This request took too long. Check your connection and try again. If you were saving a change, reload the workspace first to check whether it was saved.');if(error instanceof TypeError)throw Error('Could not reach the service. Check your connection and try again.');throw error}finally{clearTimeout(timer)}}


async function restoreSession(fetchState,view){
 view.loading();
 try{const next=await fetchState();view.ready(next);return next}
 catch(e){if(e.status===401)view.unauthorized();else view.unavailable(e);return null}
}
let sessionReady=false;
async function load(){
 const first=!sessionReady;
 const next=await restoreSession(()=>api('state'),{
  loading(){if(first){$('auth').classList.add('hidden');$('sessionRestore').classList.remove('hidden');$('sessionRestoreMessage').textContent='Checking your saved session…';$('sessionRetry').classList.add('hidden')}},
  ready(next){state=next;sessionReady=true;$('auth').classList.add('hidden');$('sessionRestore').classList.add('hidden');document.querySelector('aside').inert=false;document.querySelector('main').inert=false;document.title='Orbit | Crypto Portfolio Workspace'},
  unauthorized(){sessionReady=false;$('sessionRestore').classList.add('hidden');$('auth').classList.remove('hidden');document.querySelector('aside').inert=true;document.querySelector('main').inert=true;document.title='Sign in | Orbit Crypto Portfolio Workspace'},
  unavailable(e){if(first){$('sessionRestoreMessage').textContent='Could not reconnect to your workspace. Your session has not been cleared. Please try again.';$('sessionRetry').classList.remove('hidden')}else toast('Could not load portfolio: '+e.message)}
 });
 if(!next)return;
 try{$('email').textContent=state.profile?.name||state.email;render();if(!initialWalletSync&&state.wallets.some(w=>!w.snapshot)){initialWalletSync=true;await refresh($('syncWallets'),'sync')}queueMissingHistory()}catch(e){toast('Could not load portfolio: '+e.message)}
}
$('sessionRetry').onclick=()=>load();

function pnl(n){return '<span class="'+(n>=0?'positive':'negative')+'">'+money(n)+'</span>'}

function render(){loadDashboardPreferences();const a=state.assets;const sum=k=>a.reduce((n,x)=>n+(x[k]||0),0);const complete=a.filter(x=>x.quantity>0).every(x=>x.price!==null);$('value').textContent=a.length&&complete?money(sum('value')):'—';$('cost').textContent=money(sum('cost'));$('realized').innerHTML=pnl(sum('realized'));$('unrealized').innerHTML=a.length&&complete?pnl(sum('unrealized')):'—';$('assetCount').textContent=a.length+' assets';$('assetEmpty').classList.toggle('hidden',a.length>0);$('assets').innerHTML=a.map(x=>`<tr><td><span class="token">${esc(x.symbol.slice(0,3))}</span><b>${esc(x.symbol)}</b></td><td>${num(x.quantity)}</td><td>${money(x.average_buy)}</td><td>${x.sold?money(x.average_sell):'—'}</td><td><button data-price="${esc(x.symbol)}">${x.price===null?'+ Set price':money(x.price)}</button><div class="small muted">${quoteLabel(x.symbol)}</div></td><td>${money(x.value)}</td><td>${x.unrealized===null?'—':pnl(x.unrealized)}</td><td>${pnl(x.realized)}</td></tr>`).join('');renderTrades();renderWallets();renderHistory();renderReviews();renderNetworkSupport();renderInsights();restoreTokenControls();renderAdvanced();renderTargets();renderExchangeHoldings();renderPortfolioSummary();renderPerformance()}

function renderTrades(){renderTradeAnalytics();const q=$('search').value.toLowerCase(),side=$('sideFilter').value,from=$('dateFrom').value,to=$('dateTo').value;const rows=state.trades.filter(t=>(t.symbol+' '+t.account).toLowerCase().includes(q)&&(!side||t.side===side)&&(!from||t.date.slice(0,10)>=from)&&(!to||t.date.slice(0,10)<=to)).slice().reverse();$('tradeSummary').textContent=rows.length+' of '+state.trades.length+' trades · Gross buys '+money(rows.filter(t=>t.side==='buy').reduce((n,t)=>n+t.quantity*t.price,0))+' · Gross sells '+money(rows.filter(t=>t.side==='sell').reduce((n,t)=>n+t.quantity*t.price,0))+' · Fees '+money(rows.reduce((n,t)=>n+Number(t.fee),0));$('tradeEmpty').textContent=state.trades.length?'No trades match these filters.':'No trades yet. Add a purchase or import your history.';$('tradeEmpty').classList.toggle('hidden',rows.length>0);$('trades').innerHTML=rows.map(t=>`<tr><td>${esc(t.date.replace('T',' '))}</td><td><b>${esc(t.symbol)}</b></td><td class="${t.side==='buy'?'positive':'muted'}">${esc(t.side.toUpperCase())}</td><td>${num(t.quantity)}</td><td>${money(+t.price)}</td><td>${money(t.quantity*t.price)}</td><td>${money(+t.fee)}</td><td>${money(t.net_cash_flow)}</td><td>${t.realized_pnl==null?'<span class="muted">On sale</span>':pnl(t.realized_pnl)}</td><td>${esc(t.account)}</td><td><button data-edit-trade="${t.id}" aria-label="Edit ${esc(t.symbol)} trade">Edit</button> <button data-delete="${t.id}" aria-label="Delete ${esc(t.symbol)} ${esc(t.side)} trade from ${esc(t.date)}">×</button></td></tr>`).join('')}

