$('csvFile').onchange=()=>{resetImportPreview();const name=$('csvFile').files[0]?.name||'',match=name.match(/UTC([+-]\d+(?::\d{2})?)/i);let hours=0;if(match){const sign=match[1].startsWith('-')?-1:1,parts=match[1].slice(1).split(':');hours=sign*(Number(parts[0])+(Number(parts[1])||0)/60)}$('importOffset').value=String(hours)};$('importOffset').oninput=resetImportPreview;$('importRate').oninput=resetImportPreview;$('importAcknowledge').onchange=()=>{$('confirmImport').disabled=previewCSV===null||(previewRequiresAck&&!$('importAcknowledge').checked)};

$('previewImport').onclick=async()=>{const file=$('csvFile').files[0];if(!file){toast('Choose a CSV file first.');return}const button=$('previewImport');button.disabled=true;button.textContent='Checking rows…';resetImportPreview();const requestSeq=importPreviewSeq;try{const csv=await file.text(),options={utc_offset_minutes:Math.round(Number($('importOffset').value)*60),usdt_usd_rate:$('importRate').value},result=await api('import-preview',{csv,options});if(requestSeq!==importPreviewSeq)return;const errors=result.errors||[],trades=result.trades||[];$('importPreview').classList.remove('hidden');$('importPreview').innerHTML='<p><b>'+esc(result.source||'Orbit CSV')+'</b></p><b>'+Number(result.count??trades.length)+' valid rows · '+Number(result.duplicates||0)+' duplicates to skip · '+Number(result.skipped||0)+' non-filled orders skipped</b>'+(result.warnings||[]).map(w=>'<p class="notice small">'+esc(w)+'</p>').join('')+'<p class="small">Review genuinely identical fills: matching timestamp, amount, price, fee and account are treated as duplicates.</p>'+errors.map(e=>'<p class="negative">Row '+esc(e.row)+': '+esc(e.error)+'</p>').join('')+trades.slice(0,5).map(t=>'<p>'+esc(t.date)+' UTC · '+esc(t.side)+' '+esc(t.quantity)+' '+esc(t.symbol)+' @ '+money(Number(t.price))+' · '+esc(t.account)+'</p>').join('')+(trades.length>5?'<p>Showing the first 5 rows.</p>':'');if(!errors.length&&trades.length){previewCSV=csv;previewOptions=options;previewRequiresAck=!!result.requires_acknowledgement;$('importAcknowledgement').classList.toggle('hidden',!previewRequiresAck);$('confirmImport').disabled=previewRequiresAck}}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Preview import'}};

$('importForm').onsubmit=async e=>{e.preventDefault();if(previewCSV===null){toast('Preview the CSV before importing.');return}if(previewRequiresAck&&!$('importAcknowledge').checked){toast('Review the Binance import warnings before confirming.');return}const b=$('confirmImport');b.disabled=true;try{const result=await api('import',{csv:previewCSV,options:previewOptions,acknowledge_warnings:$('importAcknowledge').checked});$('importDialog').close();resetImportPreview();await load();toast(result.message||('Imported '+result.imported+' trades; skipped '+result.duplicates+' duplicates.'))}catch(e){toast(e.message);b.disabled=false}};

