function mountMarkets(){if(!window.OrbitMarkets)return;OrbitMarkets.mount($('marketWorkspace'),{listings:()=>api('market-listings',{}),detail:coin_id=>api('market-detail',{coin_id}),quote:(coin_id,source)=>api('market-quote',{coin_id,source}),chart:(coin_id,days,kind='line',source='coingecko',interval)=>api('market-chart',{coin_id,days,kind,source,interval:interval==='auto'?undefined:interval}),fundamentals:coin_id=>api('market-fundamentals',{coin_id}),news:coin_id=>api('market-news',{coin_id}),watchlist:()=>api('market-watchlist',{}),toggleWatch:toggleMarketWatch,alertApi:(path,data)=>api(path,data),trades:()=>state.trades||[],holdings:()=>state,saveSetup:(key,value)=>api('chart-setup-save',{key,value}),loadSetup:key=>api('chart-setup-load',{key}).then(r=>r.value),error:toast});}
function knownQuote(value){return value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))&&Number(value)>=0}

function tokenQuoteStale(t){return !!(t.stale||t.price_stale||!t.price_fetched_at||Date.now()/1000-Number(t.price_fetched_at)>900)}

function tokenPriceCells(t){const priced=knownQuote(t.price_usd),valued=knownQuote(t.value_usd),stale=tokenQuoteStale(t);const price=priced?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:8}).format(Number(t.price_usd)):'Unpriced';const observed=t.price_fetched_at?new Date(Number(t.price_fetched_at)*1000).toLocaleString():'Time unavailable';return '<td class="price-cell"><b>'+(priced&&Number(t.price_usd)>0&&Number(t.price_usd)<1e-8?'&lt;$0.00000001':price)+'</b>'+(priced?'<div class="small muted">'+esc(t.price_source||'Provider quote')+' · Quote observed '+esc(observed)+'</div>':'')+(t.price_error?'<div class="small negative">'+esc(t.price_error)+'</div>':'')+'</td><td class="value-cell"><b>'+(valued?money(Number(t.value_usd)):'Unpriced')+'</b>'+(valued?'<div class="small '+(stale?'negative':'muted')+'">'+(stale?'Stale · last known value':'Quote estimate')+'</div>':'')+'</td>'}

function walletValuationSummary(wallets,nativeValue,nativePriced){const tokens=wallets.flatMap(w=>(w.token_snapshot?.tokens||[]).filter(t=>t.quantity!==null&&t.quantity!==undefined&&!/^0(?:\.0+)?$/.test(String(t.quantity)))),priced=tokens.filter(t=>knownQuote(t.value_usd)),total=priced.reduce((n,t)=>n+Number(t.value_usd),0),stale=priced.filter(tokenQuoteStale).length,hasKnown=nativePriced+priced.length>0;return 'Known wallet value: '+(hasKnown?money(nativeValue+total):'Unpriced')+' · Native '+(nativePriced?money(nativeValue):'Unpriced')+' ('+nativePriced+'/'+wallets.length+' wallets valued) · Tokens '+(priced.length?money(total):'Unpriced')+' ('+priced.length+'/'+tokens.length+' nonzero holdings valued). '+(stale?stale+' token values stale. ':'')+'Partial coverage; unpriced assets are excluded. Token values are quote estimates. Wallet holdings are separate from recorded trades and are never added to trade holdings or used to infer P&L.'}



function preferenceKey(){return 'orbit.dashboard.v1:'+state.email}
function loadDashboardPreferences(){loadPortfolioPreferences();if(preferenceUser===state.email)return;preferenceUser=state.email;dashboardPrefs={allocation:'chain',compact:false,health:true,ledger:true};tokenControls={search:'',chain:'',sort:'value',dust:false,quote:'all'};try{const saved=JSON.parse(localStorage.getItem(preferenceKey())||'null');if(saved){dashboardPrefs={allocation:saved.allocation==='token'?'token':'chain',compact:saved.compact===true,health:saved.health!==false,ledger:saved.ledger!==false};tokenControls.sort=['value','name','low'].includes(saved.sort)?saved.sort:'value';tokenControls.dust=saved.dust===true;tokenControls.quote=['all','priced','unpriced','stale'].includes(saved.quote)?saved.quote:'all'}}catch{}}
function saveDashboardPreferences(){try{localStorage.setItem(preferenceKey(),JSON.stringify({...dashboardPrefs,sort:tokenControls.sort,dust:tokenControls.dust,quote:tokenControls.quote}));$('preferencesStatus').textContent='View saved on this browser'}catch{$('preferencesStatus').textContent='View applies to this session; browser storage unavailable'}}
function applyDashboardPreferences(){$('allocationView').value=dashboardPrefs.allocation;$('compactView').checked=dashboardPrefs.compact;$('showHealth').checked=dashboardPrefs.health;$('showLedger').checked=dashboardPrefs.ledger;document.body.classList.toggle('compact-dashboard',dashboardPrefs.compact);$('ledgerDashboard')?.classList.toggle('hidden',!dashboardPrefs.ledger);document.querySelector('#portfolioInsights [aria-label="Wallet data health"]')?.classList.toggle('hidden',!dashboardPrefs.health);$('portfolioInsights').classList.toggle('single-insight',!dashboardPrefs.health)}
for(const id of ['allocationView','compactView','showHealth','showLedger'])$(id).onchange=()=>{dashboardPrefs={allocation:$('allocationView').value,compact:$('compactView').checked,health:$('showHealth').checked,ledger:$('showLedger').checked};saveDashboardPreferences();renderInsights()};
$('resetDashboard').onclick=()=>{dashboardPrefs={allocation:'chain',compact:false,health:true,ledger:true};tokenControls={search:'',chain:'',sort:'value',dust:false,quote:'all'};saveDashboardPreferences();render()};
let dashboardPrivate=false;
$('dashboardPrivacy').onclick=()=>{dashboardPrivate=!dashboardPrivate;document.body.classList.toggle('dashboard-private',dashboardPrivate);$('dashboardPrivacy').textContent=dashboardPrivate?'Show dashboard amounts':'Hide dashboard amounts';$('dashboardPrivacy').setAttribute('aria-pressed',String(dashboardPrivate))};
load();



function renderNetworkSupport(){if(!state.network_support)return;$('providers').innerHTML=state.network_support.map(n=>'<div class="connection"><h3>'+esc(n.chain)+'</h3><span class="pill">'+(n.history_configured?'History enabled':'History setup required')+'</span><p>'+esc(n.history_coverage)+'</p>'+(['BNB Chain','Base','Arbitrum','Polygon','Sonic','Arc','Monad','Robinhood Chain','Linea'].includes(n.chain)&&!n.history_configured?'<p class="small">Set ETHERSCAN_API_KEY on the local server, then restart. Balance tracking still works.</p>':'')+'</div>').join('')}

function mountIntelligence(){if(!window.OrbitIntelligence)return;OrbitIntelligence.mount($('intelligenceWorkspace'),{overview:()=>api('intelligence-overview',{}),narratives:slug=>api('intelligence-narrative',{slug}),rsi:()=>api('intelligence-rsi',{}),venues:coin_id=>api('intelligence-venues',{coin_id}),microstructure:coin_id=>api('intelligence-flow',{coin_id}),derivatives:coin_id=>api('intelligence-derivatives',{coin_id}),exposures:coin_id=>api('intelligence-exposures',{coin_id}),listings:()=>api('market-listings',{}),watchlist:()=>api('market-watchlist',{}),toggleWatch:toggleMarketWatch,openCoin:coin_id=>{document.querySelector('[data-page="markets"]').click();window.OrbitMarkets?.openCoin?.($('marketWorkspace'),coin_id)},error:toast});}

const evmNetworks=['Ethereum','Optimism','BNB Chain','Base','Arbitrum','Polygon','Avalanche','Sonic','Gnosis','Celo','Arc','Monad','Robinhood Chain','Linea'];
$('chainCheckboxes').innerHTML=evmNetworks.map(chain=>'<label><input type="checkbox" value="'+esc(chain)+'">'+esc(chain)+'</label>').join('');
function updateChainChoices(){const compatible=evmNetworks.includes($('walletForm').elements.chain.value);$('chainChoices').classList.toggle('hidden',!compatible);if(!compatible)document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=false)}
$('walletForm').elements.chain.onchange=updateChainChoices;
$('selectAllChains').onclick=()=>document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=true);
$('clearChains').onclick=()=>document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=false);
updateChainChoices();

function mountExperience(page){const section=page==='connections'?'exchanges':page,host=$(page==='connections'?'exchangeWorkspace':page+'Workspace');experienceView?.destroy?.();experienceView=window.OrbitExperience?.mount(host,{section,api:(path,data)=>api(path,data||{}),error:toast,onProfile:name=>{$('email').textContent=name||state.email},onExchangesChanged:()=>load(),onPasswordChanged:()=>location.reload()})}
window.OrbitExperience?.installShell();

async function toggleMarketWatch(coin_id){const result=await api('market-watch-toggle',{coin_id});window.OrbitMarkets?.syncWatchlist?.($('marketWorkspace'),result);window.OrbitIntelligence?.syncWatchlist?.($('intelligenceWorkspace'),result);return result}

function renderPerformance(){if(!window.OrbitPerformance)return;if(performanceView){performanceView.update(state);return}performanceView=window.OrbitPerformance.mount($('performanceWorkspace'),{state:()=>state,api,onMarket:(id,symbol)=>{document.querySelector('[data-page="markets"]').click();if(id)window.OrbitMarkets?.openCoin($('marketWorkspace'),id);else window.OrbitMarkets?.search?.($('marketWorkspace'),symbol);window.scrollTo({top:0,behavior:'smooth'})},onExport:csv=>download(csv,'orbit-holdings-'+new Date().toISOString().slice(0,10)+'.csv'),onImport:()=>$('importButton').click(),onTrade:(symbol,day)=>{$('tradeForm').reset();$('addTrade').click();$('tradeForm').elements.symbol.value=/^[A-Z0-9_.-]{1,30}$/.test(symbol)?symbol:'';if(/^\d{4}-\d{2}-\d{2}$/.test(day||''))$('tradeForm').elements.date.value=day+'T12:00'}})}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-portfolio-position]');if(b)performanceView?.open(b.dataset.portfolioPosition)});
function loadPortfolioPreferences(){if(portfolioUser===state.email)return;portfolioUser=state.email;portfolioPrefs={dust:false,auto:true};try{const v=JSON.parse(localStorage.getItem('orbit.portfolio.view.v1:'+state.email)||'null');if(v)portfolioPrefs={dust:v.dust===true,auto:v.auto!==false}}catch{}portfolioPoller?.setEnabled(portfolioPrefs.auto)}
function savePortfolioPreferences(){try{localStorage.setItem('orbit.portfolio.view.v1:'+state.email,JSON.stringify(portfolioPrefs))}catch{}portfolioPoller?.setEnabled(portfolioPrefs.auto);renderPortfolioSummary();performanceView?.update(state)}
function renderPortfolioSummary(){if(!window.OrbitPortfolio)return;document.body.classList.toggle('portfolio-hide-small',portfolioPrefs.dust);for(const id of ['portfolioSummary','connectionsSummary']){const host=$(id);if(!host)continue;const helpStates=new Map([...host.querySelectorAll('details')].map(d=>[d.className,d.open]));host.innerHTML=window.OrbitPortfolio.render(state,{...portfolioPrefs,status:portfolioStatus},id==='connectionsSummary');for(const detail of host.querySelectorAll('details'))if(helpStates.has(detail.className))detail.open=helpStates.get(detail.className);host.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-portfolio-connect'))document.querySelector('[data-page="connections"]').click();else if(b.hasAttribute('data-portfolio-import'))$('importButton').click();else if(b.hasAttribute('data-portfolio-record')){$('tradeForm').reset();$('addTrade').click()}else if(b.hasAttribute('data-portfolio-auto')){portfolioPrefs.auto=!portfolioPrefs.auto;savePortfolioPreferences()}else if(b.hasAttribute('data-portfolio-refresh'))portfolioPoller?.tick(true)};host.onchange=e=>{if(e.target.hasAttribute('data-portfolio-dust')){portfolioPrefs.dust=e.target.checked;savePortfolioPreferences()}}}}
const portfolioPoller=window.OrbitPortfolio?.poller({now:()=>Date.now(),active:()=>sessionReady&&!document.hidden&&!document.querySelector('dialog[open]')&&!document.querySelector('main input:focus,main textarea:focus,main select:focus')&&!$('refreshPrices').disabled,refresh:async()=>{portfolioStatus='Updating prices…';renderPortfolioSummary();await api('refresh-prices',{});await load();portfolioStatus='Prices checked '+new Date().toLocaleTimeString()+'. Provider timestamps and cache limits apply.';renderPortfolioSummary();renderTradeAnalytics();if(!$('connections').classList.contains('hidden')&&!document.querySelector('[data-ex-form="exchange"] input[name="api_key"]')?.value&&!document.querySelector('[data-ex-form="exchange"] input[name="api_secret"]')?.value)await experienceView?.reload?.()},error:e=>{portfolioStatus='Price refresh unavailable; last saved values retained. Retrying later.';renderPortfolioSummary();renderTradeAnalytics();if(e.status===401)load()}});
if(portfolioPoller){window.setInterval(()=>portfolioPoller.tick(),15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)portfolioPoller.tick()})}

function renderExchangeHoldings(){const host=$('overviewExchanges');if(!host)return;const accounts=state.exchanges||[];host.classList.toggle('hidden',!accounts.length);if(!accounts.length){host.innerHTML='';return}const rows=accounts.flatMap(a=>(a.snapshot?.balances||[]).map(b=>({...b,connection_id:a.id,account:a.label,updated:a.snapshot.updated_at}))),priced=rows.filter(b=>b.value_usd!==null&&b.value_usd!==undefined&&Number.isFinite(Number(b.value_usd))&&Number(b.value_usd)>=0),value=priced.reduce((n,b)=>n+Number(b.value_usd),0);host.innerHTML='<span class="eyebrow">CONNECTED EXCHANGES</span><h2>Binance holdings</h2><p>Known value: <strong>'+ (priced.length?money(value):'Unpriced')+'</strong> · '+priced.length+' of '+rows.length+' balances priced. Snapshot values; use Sync balances in Connections to refresh.</p><div class="table-wrap"><table><thead><tr><th>Asset / account</th><th>Amount</th><th>USD value</th><th>Last sync</th></tr></thead><tbody>'+priced.map(b=>'<tr data-portfolio-small="'+(b.value_usd!==null&&b.value_usd!==undefined&&Number.isFinite(Number(b.value_usd))&&Number(b.value_usd)>=0&&Number(b.value_usd)<1)+'"><td><button class="performance-asset" data-portfolio-position="'+esc('exchange:'+b.connection_id+':'+b.asset)+'">'+esc(b.display_asset||b.asset)+'</button>'+ (b.account_type==='Earn'?' <span class="small muted">Earn</span>':'')+'<div class="small muted">'+esc(b.account)+'</div></td><td>'+esc(b.display_quantity??b.quantity)+'</td><td>'+ (b.value_usd===null||b.value_usd===undefined||!Number.isFinite(Number(b.value_usd))?'Unpriced':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:Number(b.value_usd)>0&&Number(b.value_usd)<.01?8:2}).format(Number(b.value_usd)))+'</td><td>'+esc(b.updated?new Date(b.updated*1000).toLocaleString():'Unavailable')+'</td></tr>').join('')+'</tbody></table></div><p class="small muted">Spot and verified Flexible / Locked Earn positions. Unpriced assets are hidden. These balances are separate from wallet and recorded-trade totals to avoid double counting. Trade history and cost basis are not imported.</p>'}

function renderTradeAnalytics(){
 const host=$('tradeAnalytics');if(!host)return;
 const assets=state.assets||[],held=assets.filter(a=>Number(a.quantity)>0),priced=held.filter(a=>a.value!==null),sum=(rows,k)=>rows.reduce((n,a)=>n+Number(a[k]||0),0),complete=held.every(a=>a.value!==null),realized=sum(assets,'realized'),unrealized=complete?sum(held,'unrealized'):null,cost=sum(held,'cost'),value=complete?sum(held,'value'):null;
 const metric=(label,v,note)=>`<div class="trade-stat"><span>${label}</span><strong>${v}</strong><small>${note}</small></div>`;
 const bars=assets.filter(a=>Number(a.cost)>0||Number(a.value)>0),max=Math.max(1,...bars.flatMap(a=>[Number(a.cost)||0,Number(a.value)||0]));
 host.innerHTML=`<div class="trade-stat-grid">${metric(complete?'Current holding value':'Priced holding subtotal',priced.length?money(sum(priced,'value')):'—',priced.length+' / '+held.length+' held coins priced')}${metric('Remaining cost',money(cost),'Purchase fees included')}${metric('Realized P&L',pnl(realized),'Recorded sales · after fees')}${metric(complete?'Unrealized P&L':'Unrealized · priced coins',priced.length?pnl(sum(priced,'unrealized')):'—',cost&&unrealized!==null?(unrealized/cost*100).toFixed(2)+'% on remaining cost':'Partial coverage · '+priced.length+' / '+held.length+' coins')}</div><div class="trade-visual-grid"><section class="trade-visual"><h3>Cost versus current value</h3><p class="small muted">Remaining holdings · <span class="trade-cost-key">■ Cost</span> <span class="trade-value-key">■ Value</span></p>${bars.length?bars.map(a=>`<div class="trade-bar-row"><b>${esc(a.symbol)}</b><div><div class="trade-bar cost" style="width:${Number(a.cost)/max*100}%"></div><div class="trade-bar value" style="width:${Number(a.value||0)/max*100}%"></div></div><small>${money(a.cost)} / ${money(a.value)}</small></div>`).join(''):'<p>Record a purchase to compare cost and value.</p>'}</section><section class="trade-visual"><h3>Profit & loss by coin</h3><p class="small muted">Across all recorded trades · weighted-average cost</p><div class="table-wrap"><table><thead><tr><th>Coin</th><th>Avg buy</th><th>Value</th><th>Realized</th><th>Unrealized</th></tr></thead><tbody>${assets.map(a=>`<tr><td><b>${esc(a.symbol)}</b><small>${num(a.quantity)} held</small></td><td>${money(a.average_buy)}</td><td>${money(a.value)}</td><td>${pnl(a.realized)}</td><td>${a.unrealized===null?'—':pnl(a.unrealized)}</td></tr>`).join('')}</tbody></table></div></section></div><p class="small muted" role="status">${esc(portfolioStatus||'Quotes use the last saved provider prices.')} Current values refresh automatically every minute while this tab is active (unless paused). Execution prices and trade values stay fixed. These results use recorded trades only; connected balances are separate. Missing quotes are never treated as zero. Editing a trade recalculates the full history.</p>`;
}
